WITH base AS (SELECT id, order_id, method, amount, paid_at, CAST(amount AS INT) AS amount_int, SUBSTRING(status, 1, 2) AS status_prefix FROM payments WHERE paid_at >= TIMESTAMP '2023-06-11 03:00:00'), with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM base), islands AS (SELECT id, order_id, method, paid_at, amount_int, SUM(new_group_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT CASE WHEN amount_int >= 72 THEN 'LARGE' ELSE 'SMALL' END AS amount_int_tier, method, CASE WHEN session_no >= 8 THEN 'HIGH' ELSE 'LOW' END AS session_no_tier, COUNT(CASE WHEN method = 'paypal' THEN 1 END) AS paypal_count, ROUND(SUM(amount_int) / NULLIF(COUNT(CASE WHEN method = 'cash' THEN 1 END), 0), 2) AS amount_int_per_cash FROM islands GROUP BY CASE WHEN amount_int >= 72 THEN 'LARGE' ELSE 'SMALL' END, method, CASE WHEN session_no >= 8 THEN 'HIGH' ELSE 'LOW' END ORDER BY amount_int_tier NULLS FIRST;
